//! Original Rust JavaScript runtime subset; not yet a complete ECMAScript implementation.
mod lexer;mod parser;
use std::{cell::RefCell,collections::HashMap,rc::Rc};
pub use lexer::{LexError,Token,TokenKind};use parser::{Expr,ParseError,Parser,Stmt};
#[derive(Clone,Debug,PartialEq)]pub enum Value{Number(f64),String(String),Boolean(bool),Null,Undefined,Array(Rc<RefCell<Vec<Value>>>),Object(Rc<RefCell<HashMap<String,Value>>>)}
impl Value{fn truthy(&self)->bool{match self{Self::Boolean(v)=>*v,Self::Null|Self::Undefined=>false,Self::Number(n)=>*n!=0.0&&!n.is_nan(),Self::String(s)=>!s.is_empty(),_=>true}}fn display(&self)->String{match self{Self::Number(n)if n.fract()==0.0=>format!("{n:.0}"),Self::Number(n)=>n.to_string(),Self::String(s)=>s.clone(),Self::Boolean(v)=>v.to_string(),Self::Null=>"null".into(),Self::Undefined=>"undefined".into(),Self::Array(a)=>a.borrow().iter().map(|v|if matches!(v,Value::Null|Value::Undefined){String::new()}else{v.display()}).collect::<Vec<_>>().join(","),Self::Object(_)=>"[object Object]".into()}}}
#[derive(Debug,PartialEq)]pub enum EngineError{Lex(LexError),Parse(ParseError),Type(String),Reference(String),Syntax(String)}
impl std::fmt::Display for EngineError{fn fmt(&self,f:&mut std::fmt::Formatter<'_>)->std::fmt::Result{match self{Self::Lex(e)=>write!(f,"lex error: {e}"),Self::Parse(e)=>write!(f,"parse error: {e}"),Self::Type(s)=>write!(f,"type error: {s}"),Self::Reference(s)=>write!(f,"reference error: {s}"),Self::Syntax(s)=>write!(f,"syntax error: {s}")}}}impl std::error::Error for EngineError{}impl From<LexError> for EngineError{fn from(e:LexError)->Self{Self::Lex(e)}}impl From<ParseError> for EngineError{fn from(e:ParseError)->Self{Self::Parse(e)}}
#[derive(Clone,Debug)]struct Binding{value:Value,constant:bool}
#[derive(Clone)]struct Function{params:Vec<String>,body:Vec<Stmt>}
enum Flow{Value(Value),Return(Value),Break,Continue}
pub struct Runtime{scopes:Vec<HashMap<String,Binding>>,functions:HashMap<String,Function>,output:Vec<String>,call_depth:usize,loop_depth:usize}
impl Default for Runtime{fn default()->Self{Self{scopes:vec![HashMap::new()],functions:HashMap::new(),output:Vec::new(),call_depth:0,loop_depth:0}}}
impl Runtime{
pub fn new()->Self{Self::default()}pub fn execute(&mut self,source:&str)->Result<Value,EngineError>{let p=Parser::new(lexer::tokenize(source)?).parse_program()?;match self.execute_statements(p)?{Flow::Value(v)=>Ok(v),Flow::Return(_)=>Err(EngineError::Syntax("return outside a function".into())),Flow::Break=>Err(EngineError::Syntax("break outside a loop".into())),Flow::Continue=>Err(EngineError::Syntax("continue outside a loop".into()))}}pub fn take_output(&mut self)->Vec<String>{std::mem::take(&mut self.output)}pub fn get_global(&self,name:&str)->Option<&Value>{self.scopes.first()?.get(name).map(|b|&b.value)}
fn execute_statements(&mut self,ss:Vec<Stmt>)->Result<Flow,EngineError>{let mut last=Value::Undefined;for s in ss{match self.execute_statement(s)?{Flow::Value(v)=>last=v,r@Flow::Return(_)=>return Ok(r),Flow::Break=>return Ok(Flow::Break),Flow::Continue=>return Ok(Flow::Continue)}}Ok(Flow::Value(last))}
fn execute_scoped(&mut self,ss:Vec<Stmt>)->Result<Flow,EngineError>{self.scopes.push(HashMap::new());let r=self.execute_statements(ss);self.scopes.pop();r}
fn execute_statement(&mut self,s:Stmt)->Result<Flow,EngineError>{match s{
Stmt::Expression(e)=>Ok(Flow::Value(self.evaluate(e)?)),
Stmt::Declaration{name,value,constant}=>{if self.scopes.last().is_some_and(|s|s.contains_key(&name)){return Err(EngineError::Syntax(format!("'{name}' has already been declared in this scope")))}let v=self.evaluate(value)?;self.scopes.last_mut().unwrap().insert(name,Binding{value:v.clone(),constant});Ok(Flow::Value(v))}
Stmt::Block(b)=>self.execute_scoped(b),
Stmt::If{condition,then_branch,else_branch}=>if self.evaluate(condition)?.truthy(){self.execute_scoped(then_branch)}else if let Some(b)=else_branch{self.execute_scoped(b)}else{Ok(Flow::Value(Value::Undefined))},
Stmt::While{condition,body}=>{self.loop_depth+=1;let result=(||{let mut last=Value::Undefined;let mut iterations=0usize;while self.evaluate(condition.clone())?.truthy(){if iterations>=1_000_000{return Err(EngineError::Type("maximum loop iterations exceeded".into()))}iterations+=1;match self.execute_scoped(body.clone())?{Flow::Value(v)=>last=v,r@Flow::Return(_)=>return Ok(r),Flow::Break=>break,Flow::Continue=>continue}}Ok(Flow::Value(last))})();self.loop_depth-=1;result},
Stmt::For{init,condition,update,body}=>{self.scopes.push(HashMap::new());self.loop_depth+=1;let result=(||{if let Some(i)=init{self.execute_statement(*i)?;}let mut last=Value::Undefined;let mut iterations=0usize;while condition.as_ref().map(|c|self.evaluate(c.clone()).map(|v|v.truthy())).transpose()?.unwrap_or(true){if iterations>=1_000_000{return Err(EngineError::Type("maximum loop iterations exceeded".into()))}iterations+=1;match self.execute_scoped(body.clone())?{Flow::Value(v)=>last=v,r@Flow::Return(_)=>return Ok(r),Flow::Break=>break,Flow::Continue=>{}}if let Some(u)=update.clone(){last=self.evaluate(u)?;}}Ok(Flow::Value(last))})();self.loop_depth-=1;self.scopes.pop();result},
Stmt::Function{name,params,body}=>{if self.functions.contains_key(&name)||self.scopes[0].contains_key(&name){return Err(EngineError::Syntax(format!("'{name}' has already been declared")))}self.functions.insert(name,Function{params,body});Ok(Flow::Value(Value::Undefined))},
Stmt::Return(e)=>{if self.call_depth==0{return Err(EngineError::Syntax("return outside a function".into()))}Ok(Flow::Return(if let Some(e)=e{self.evaluate(e)?}else{Value::Undefined}))},Stmt::Break=>if self.loop_depth==0{Err(EngineError::Syntax("break outside a loop".into()))}else{Ok(Flow::Break)},Stmt::Continue=>if self.loop_depth==0{Err(EngineError::Syntax("continue outside a loop".into()))}else{Ok(Flow::Continue)}
}}
fn evaluate(&mut self,e:Expr)->Result<Value,EngineError>{match e{
Expr::Literal(v)=>Ok(v),Expr::Identifier(n)=>self.lookup(&n).map(|b|b.value.clone()).ok_or_else(||EngineError::Reference(format!("{n} is not defined"))),
Expr::Update{name,delta,prefix}=>{let i=self.scopes.iter().rposition(|s|s.contains_key(&name)).ok_or_else(||EngineError::Reference(format!("{name} is not defined")))?;if self.scopes[i][&name].constant{return Err(EngineError::Type(format!("assignment to constant variable '{name}'")))}let old=self.scopes[i][&name].value.clone();let next=Value::Number(self.to_number(old.clone())?+delta as f64);self.scopes[i].get_mut(&name).unwrap().value=next.clone();Ok(if prefix{next}else{old})},
Expr::Assign{name,value}=>{let i=self.scopes.iter().rposition(|s|s.contains_key(&name)).ok_or_else(||EngineError::Reference(format!("{name} is not defined")))?;if self.scopes[i][&name].constant{return Err(EngineError::Type(format!("assignment to constant variable '{name}'")))}let v=self.evaluate(*value)?;self.scopes[i].get_mut(&name).unwrap().value=v.clone();Ok(v)},
Expr::SetMember{object,key,value}=>{let target=self.evaluate(*object)?;let v=self.evaluate(*value)?;match target{Value::Object(o)=>{o.borrow_mut().insert(key,v.clone());Ok(v)},Value::Array(a)if key=="length"=>{let n=self.to_number(v.clone())? as usize;a.borrow_mut().resize(n,Value::Undefined);Ok(Value::Number(n as f64))},_=>Err(EngineError::Type("cannot set property on this value".into()))}},
Expr::SetIndex{object,index,value}=>{let target=self.evaluate(*object)?;let ix=self.evaluate(*index)?;let v=self.evaluate(*value)?;match target{Value::Array(a)=>{let i=self.index_number(ix)?;if i>1_000_000{return Err(EngineError::Type("array index too large".into()))}let mut a=a.borrow_mut();if i>=a.len(){a.resize(i+1,Value::Undefined)}a[i]=v.clone();Ok(v)},Value::Object(o)=>{o.borrow_mut().insert(ix.display(),v.clone());Ok(v)},_=>Err(EngineError::Type("cannot set indexed property on this value".into()))}},
Expr::Member{object,key}=>{let o=self.evaluate(*object)?;self.get_property(o,&key)},
Expr::Index{object,index}=>{let o=self.evaluate(*object)?;let i=self.evaluate(*index)?;self.get_property(o,&i.display())},
Expr::Array(items)=>{let mut values=Vec::with_capacity(items.len());for e in items{values.push(self.evaluate(e)?)}Ok(Value::Array(Rc::new(RefCell::new(values))))},
Expr::Object(props)=>{let mut values=HashMap::new();for(k,e)in props{values.insert(k,self.evaluate(e)?);}Ok(Value::Object(Rc::new(RefCell::new(values))))},
Expr::Conditional{condition,yes,no}=>if self.evaluate(*condition)?.truthy(){self.evaluate(*yes)}else{self.evaluate(*no)},
Expr::Unary{op,value}=>{let v=self.evaluate(*value)?;match op.as_str(){"!"=>Ok(Value::Boolean(!v.truthy())),"typeof"=>Ok(Value::String(match v{Value::Undefined=>"undefined",Value::Null=>"object",Value::Boolean(_)=>"boolean",Value::Number(_)=>"number",Value::String(_)=>"string",Value::Array(_)|Value::Object(_)=>"object"}.into())),"void"=>Ok(Value::Undefined),"+"=>self.to_number(v).map(Value::Number),"-"=>self.to_number(v).map(|n|Value::Number(-n)),_=>Err(EngineError::Syntax(format!("unsupported unary operator {op}")))}},
Expr::Binary{op,left,right}=>{let a=self.evaluate(*left)?;if op=="&&"&&!a.truthy(){return Ok(a)}if op=="||"&&a.truthy(){return Ok(a)}let b=self.evaluate(*right)?;self.binary(&op,a,b)},
Expr::MethodCall{object,key,args}=>{let target=self.evaluate(*object)?;let mut values=Vec::with_capacity(args.len());for a in args{values.push(self.evaluate(a)?)}match (target,key.as_str()){(Value::Array(a),"push")=>{let mut a=a.borrow_mut();a.extend(values);Ok(Value::Number(a.len() as f64))},(Value::Array(a),"pop")=>Ok(a.borrow_mut().pop().unwrap_or(Value::Undefined)),(Value::Array(a),"join")=>{let sep=values.first().map(Value::display).unwrap_or_else(||",".into());Ok(Value::String(a.borrow().iter().map(|v|if matches!(v,Value::Null|Value::Undefined){String::new()}else{v.display()}).collect::<Vec<_>>().join(&sep)))},(Value::Array(a),"reverse")=>{a.borrow_mut().reverse();Ok(Value::Array(a))},(Value::Array(a),"includes")=>Ok(Value::Boolean(a.borrow().iter().any(|v|values.first().is_some_and(|x|equal(v,x))))),(Value::Array(a),"indexOf")=>Ok(Value::Number(a.borrow().iter().position(|v|values.first().is_some_and(|x|equal(v,x))).map(|i|i as f64).unwrap_or(-1.0))),(Value::String(s),"includes")=>Ok(Value::Boolean(values.first().is_some_and(|v|s.contains(&v.display())))),(Value::String(s),"toUpperCase")=>Ok(Value::String(s.to_uppercase())),(Value::String(s),"toLowerCase")=>Ok(Value::String(s.to_lowercase())),(Value::String(s),"trim")=>Ok(Value::String(s.trim().into())),(Value::String(s),"startsWith")=>Ok(Value::Boolean(values.first().is_some_and(|v|s.starts_with(&v.display())))),(Value::String(s),"endsWith")=>Ok(Value::Boolean(values.first().is_some_and(|v|s.ends_with(&v.display())))),(Value::String(s),"indexOf")=>Ok(Value::Number(values.first().map(|v|s.find(&v.display()).map(|i|s[..i].encode_utf16().count() as f64).unwrap_or(-1.0)).unwrap_or(-1.0))),(target,method)=>Err(EngineError::Type(format!("method '{method}' is not supported on {}",match target{Value::Array(_)=>"array",Value::String(_)=>"string",Value::Object(_)=>"object",_=>"this value"})))}} ,Expr::Call{name,args}=>{let fun=self.functions.get(&name).cloned().ok_or_else(||EngineError::Reference(format!("{name} is not defined")))?;if self.call_depth>=512{return Err(EngineError::Type("maximum call depth exceeded".into()))}let mut values=Vec::with_capacity(args.len());for a in args{values.push(self.evaluate(a)?)}self.call_depth+=1;self.scopes.push(HashMap::new());for(i,p)in fun.params.iter().enumerate(){self.scopes.last_mut().unwrap().insert(p.clone(),Binding{value:values.get(i).cloned().unwrap_or(Value::Undefined),constant:false});}let result=self.execute_statements(fun.body);self.scopes.pop();self.call_depth-=1;match result?{Flow::Value(_)=>Ok(Value::Undefined),Flow::Return(v)=>Ok(v),Flow::Break=>Err(EngineError::Syntax("break outside a loop".into())),Flow::Continue=>Err(EngineError::Syntax("continue outside a loop".into()))}}
}}
fn lookup(&self,n:&str)->Option<&Binding>{self.scopes.iter().rev().find_map(|s|s.get(n))}
fn index_number(&self,v:Value)->Result<usize,EngineError>{let n=self.to_number(v)?;if !n.is_finite()||n<0.0||n.fract()!=0.0{return Err(EngineError::Type("array index must be a non-negative integer".into()))}Ok(n as usize)}
fn get_property(&self,o:Value,key:&str)->Result<Value,EngineError>{match o{Value::Object(v)=>Ok(v.borrow().get(key).cloned().unwrap_or(Value::Undefined)),Value::Array(v)=>{if key=="length"{return Ok(Value::Number(v.borrow().len() as f64))}if let Ok(i)=key.parse::<usize>(){return Ok(v.borrow().get(i).cloned().unwrap_or(Value::Undefined))}Ok(Value::Undefined)},Value::String(s)=>{if key=="length"{return Ok(Value::Number(s.encode_utf16().count() as f64))}if let Ok(i)=key.parse::<usize>(){return Ok(s.chars().nth(i).map(|c|Value::String(c.to_string())).unwrap_or(Value::Undefined))}Ok(Value::Undefined)},_=>Err(EngineError::Type("cannot read property on this value".into()))}}
fn to_number(&self,v:Value)->Result<f64,EngineError>{match v{Value::Number(n)=>Ok(n),Value::Boolean(b)=>Ok(if b{1.0}else{0.0}),Value::Null=>Ok(0.0),Value::String(s)if s.trim().is_empty()=>Ok(0.0),Value::String(s)=>Ok(s.trim().parse().unwrap_or(f64::NAN)),Value::Undefined=>Ok(f64::NAN),_=>Ok(f64::NAN)}}
fn binary(&self,op:&str,a:Value,b:Value)->Result<Value,EngineError>{if op=="+"&&(matches!(a,Value::String(_))||matches!(b,Value::String(_))){return Ok(Value::String(format!("{}{}",a.display(),b.display())))}if op=="==="||op=="!=="{let e=equal(&a,&b);return Ok(Value::Boolean(if op=="==="{e}else{!e}))}if op=="=="||op=="!="{let e=loose(&a,&b,self)?;return Ok(Value::Boolean(if op=="=="{e}else{!e}))}if let(Value::String(x),Value::String(y))=(&a,&b){if matches!(op,"<"|"<="|">"|">="){return Ok(Value::Boolean(match op{"<"=>x<y,"<="=>x<=y,">"=>x>y,">="=>x>=y,_=>false}))}}if op=="&&"{return Ok(if a.truthy(){b}else{a})}if op=="||"{return Ok(if a.truthy(){a}else{b})}let x=self.to_number(a)?;let y=self.to_number(b)?;Ok(match op{"+"=>Value::Number(x+y),"-"=>Value::Number(x-y),"*"=>Value::Number(x*y),"/"=>Value::Number(x/y),"%"=>Value::Number(x%y),"**"=>Value::Number(x.powf(y)),"<"=>Value::Boolean(x<y),"<="=>Value::Boolean(x<=y),">"=>Value::Boolean(x>y),">="=>Value::Boolean(x>=y),_=>return Err(EngineError::Syntax(format!("unsupported binary operator {op}")))})}
}
fn equal(a:&Value,b:&Value)->bool{match(a,b){(Value::Number(x),Value::Number(y))=>x==y,(Value::String(x),Value::String(y))=>x==y,(Value::Boolean(x),Value::Boolean(y))=>x==y,(Value::Null,Value::Null)|(Value::Undefined,Value::Undefined)=>true,(Value::Array(x),Value::Array(y))=>Rc::ptr_eq(x,y),(Value::Object(x),Value::Object(y))=>Rc::ptr_eq(x,y),_=>false}}
fn loose(a:&Value,b:&Value,r:&Runtime)->Result<bool,EngineError>{if equal(a,b){return Ok(true)}match(a,b){(Value::Null,Value::Undefined)|(Value::Undefined,Value::Null)=>Ok(true),(Value::Number(_),Value::String(_))|(Value::String(_),Value::Number(_))|(Value::Boolean(_),_)|(_,Value::Boolean(_))=>Ok(r.to_number(a.clone())?==r.to_number(b.clone())?),_=>Ok(false)}}
#[cfg(test)]mod tests{use super::*;#[test]fn compound_assignments(){let mut r=Runtime::new();assert_eq!(r.execute("let x=10;x+=5;x-=2;x*=3;x/=2;x%=7;x;").unwrap(),Value::Number(5.0));let mut r=Runtime::new();assert_eq!(r.execute("let s=\"hi\";s+=\"!\";s;").unwrap(),Value::String("hi!".into()));}#[test]fn compound_assignment_const_is_error(){let mut r=Runtime::new();assert!(r.execute("const x=1;x+=1;").is_err());}#[test]fn increment_and_decrement(){let mut r=Runtime::new();assert_eq!(r.execute("let x=2; x++; ++x; x--; --x; x;").unwrap(),Value::Number(2.0));let mut r=Runtime::new();assert_eq!(r.execute("let x=3; x++;").unwrap(),Value::Number(3.0));assert_eq!(r.execute("let x=3; ++x;").unwrap(),Value::Number(4.0));}#[test]fn increment_const_is_error(){let mut r=Runtime::new();assert!(r.execute("const x=1; x++;").is_err());}#[test]fn functions(){let mut r=Runtime::new();assert_eq!(r.execute("function add(a,b){return a+b;}add(2,5);").unwrap(),Value::Number(7.0))}#[test]fn arrays_and_mutation(){let mut r=Runtime::new();assert_eq!(r.execute("let a=[3,4];a[1]=9;a[0]+a[1];").unwrap(),Value::Number(12.0))}#[test]fn object_properties(){let mut r=Runtime::new();assert_eq!(r.execute("let o={x:4, name:'hi'};o.x=7;o.x;").unwrap(),Value::Number(7.0));assert_eq!(r.execute("o['name'];").unwrap(),Value::String("hi".into()))}#[test]fn array_length(){let mut r=Runtime::new();assert_eq!(r.execute("let a=[1,2,3];a.length;").unwrap(),Value::Number(3.0))}#[test]fn typeof_operator(){let mut r=Runtime::new();assert_eq!(r.execute("typeof 1;").unwrap(),Value::String("number".into()));assert_eq!(r.execute("typeof \"x\";").unwrap(),Value::String("string".into()));assert_eq!(r.execute("typeof true;").unwrap(),Value::String("boolean".into()));assert_eq!(r.execute("typeof undefined;").unwrap(),Value::String("undefined".into()));assert_eq!(r.execute("typeof null;").unwrap(),Value::String("object".into()));}#[test]fn void_operator(){let mut r=Runtime::new();assert_eq!(r.execute("void 123;").unwrap(),Value::Undefined);assert_eq!(r.execute("let x=0;void (x=5);x;").unwrap(),Value::Number(5.0));}#[test]fn conditional_operator(){let mut r=Runtime::new();assert_eq!(r.execute("true ? 4 : 9;").unwrap(),Value::Number(4.0));assert_eq!(r.execute("false ? 4 : 9;").unwrap(),Value::Number(9.0));assert_eq!(r.execute("let x=0;true ? 7 : (x=1);x;").unwrap(),Value::Number(0.0));}#[test]fn array_methods(){let mut r=Runtime::new();assert_eq!(r.execute("let a=[1];a.push(2);a.length;").unwrap(),Value::Number(2.0));assert_eq!(r.execute("a.includes(2);").unwrap(),Value::Boolean(true));assert_eq!(r.execute("a.indexOf(2);").unwrap(),Value::Number(1.0));assert_eq!(r.execute("a.pop();").unwrap(),Value::Number(2.0));assert_eq!(r.execute("a.length;").unwrap(),Value::Number(1.0));}#[test]fn string_methods(){let mut r=Runtime::new();assert_eq!(r.execute('"abc".toUpperCase();').unwrap(),Value::String("ABC".into()));assert_eq!(r.execute('"abc".includes("b");').unwrap(),Value::Boolean(true));}#[test]fn additional_array_methods(){let mut r=Runtime::new();assert_eq!(r.execute("let a=[1,2,3];a.reverse();a.join(\"-\");").unwrap(),Value::String("3-2-1".into()));}#[test]fn additional_string_methods(){let mut r=Runtime::new();assert_eq!(r.execute("\"  hi  \".trim();").unwrap(),Value::String("hi".into()));assert_eq!(r.execute("\"hello\".startsWith(\"he\");").unwrap(),Value::Boolean(true));assert_eq!(r.execute("\"hello\".endsWith(\"lo\");").unwrap(),Value::Boolean(true));}#[test]fn classic_for_loop(){let mut r=Runtime::new();assert_eq!(r.execute("let sum=0;for(let i=0;i<5;i=i+1){sum=sum+i;}sum;").unwrap(),Value::Number(10.0));}#[test]fn for_loop_optional_clauses(){let mut r=Runtime::new();assert_eq!(r.execute("let i=0;for(;i<3;){i=i+1;}i;").unwrap(),Value::Number(3.0));}#[test]fn break_in_for_loop(){let mut r=Runtime::new();assert_eq!(r.execute("let i=0;for(;i<10;i=i+1){if(i===4){break;}}i;").unwrap(),Value::Number(4.0));}#[test]fn continue_in_for_loop_runs_update(){let mut r=Runtime::new();assert_eq!(r.execute("let sum=0;for(let i=0;i<5;i=i+1){if(i===2){continue;}sum=sum+i;}sum;").unwrap(),Value::Number(8.0));}#[test]fn continue_in_while_loop(){let mut r=Runtime::new();assert_eq!(r.execute("let i=0;let sum=0;while(i<4){i=i+1;if(i===2){continue;}sum=sum+i;}sum;").unwrap(),Value::Number(8.0));}#[test]fn break_outside_loop_is_error(){let mut r=Runtime::new();assert!(r.execute("break;").is_err());}#[test]fn continue_outside_loop_is_error(){let mut r=Runtime::new();assert!(r.execute("continue;").is_err());}#[test]fn statements_after_loop_control_are_not_skipped(){let mut r=Runtime::new();assert_eq!(r.execute("let x=0;while(true){x=1;break;x=9;}x;").unwrap(),Value::Number(1.0));}#[test]fn shared_reference(){let mut r=Runtime::new();assert_eq!(r.execute("let a=[1];let b=a;b[0]=8;a[0];").unwrap(),Value::Number(8.0))}}